head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > setIgnoreStatus]<br/>Column 의 ignoreStatus 속성을 설정합니다.",
    "validation" : [
        "전체 Column 의 ignoreStatus 속성을 모두 설정하거나 특정 Column 만 설정합니다.",
        "colID(선택) 파라미터로 ignoreStatus 속성을 설정하려는 Column 의 ID 를 설정합니다.",
        "ignore(필수) 파라미터로 ignoreStatus 의 속성값을 true/false 로 설정합니다.",
        "ignore(필수) 파라미터로 true 설정 시 Cloumn 의 데이터가 변경되어도 Row 의 상태값을 변경하지 않고 유지합니다.",
        "ignore(필수) 파라미터로 false 설정 시 Cloumn 의 데이터가 변경되면 Row 의 상태값을 변경합니다.",
        "사용자의 조작이나 메소드에 의해 데이터가 변경될때 ignoreStatus 속성의 영향을 받습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}   



scwin.btn_setCellData_onclick = function (e) {
    let colID = par_colID.getText();

    if (colID == "") {
        for (var i=0; i<4; i++) {
            for (var j=0; j<4; j++) {
                target1.setCellData(i, j, "change");
            }            
        }            
    }
    else {
        for (var i=0; i<4; i++) {
            target1.setCellData(i, colID, "change");
        }
    }    

    scwin.btn_getAllJSON_onclick();
};



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_setIgnoreStatus_onclick = function (e) {
    let colID = par_colID.getText();
    let ignore = par_ignore.getText();

    if (ignore == "true")
        ignore = true;
    else if (ignore == "false")
        ignore = false;
    else
        ignore = null;

    if (colID == "")
        target1.setIgnoreStatus(colID);
    else
        target1.setIgnoreStatus(colID, ignore);
};
